/* Review UI; all binary encoding is delegated to shared codecs. */
(() => {
'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const all=new Map();let host;const labels=['空闲','连接中','成功','失败','未知'];
function get(c){if(!all.has(c.productId))all.set(c.productId,{remoteType:0,status:4,simulatedStatus:4,queryPending:false,submitted:false,frame:null,error:null,logs:[],size:128,template:c.templateVersion||'flat-v1-draft',consumer:'both',long:null,caps:null});return all.get(c.productId);}
const button=(text,id,disabled=false)=>`<button type="button" class="btn small" data-bench-action="${id}" ${disabled?'disabled':''}>${text}</button>`;
const select=(id,items,v)=>`<select data-bench-field="${id}" aria-label="${({network:'网络类型',status:'设备状态模拟',size:'Value字节数',template:'验算模板',consumer:'消费者模板能力'})[id]}">${items.map(([x,l])=>`<option value="${x}" ${String(x)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
const alert=s=>s.error?`<div class="banner amber" role="alert">${esc(s.error)}</div>`:'';
function renderPublic(c){const s=get(c);return `<section class="panel-body app-workbench" data-note="10"><h3>公共预定义指令 <span class="tag outline">纯本地演示</span></h3><p class="help">产品采用已确认的公共能力。下方只使用虚构参数，不连接设备、网络或平台。</p><table class="readonly-table"><thead><tr><th>接口</th><th>SID / CID</th><th>消息规则</th><th>产品采用要求</th></tr></thead><tbody>${[['命令能力协商','01 / 03','请求与响应','双方分别声明，实际使用交集'],['设备信息','01 / 04','TLV查询及返回','明确身份字段，不按长度猜格式'],['电量','01 / 0B','查询 / 上报','请求side可选；每组返回side必填'],['广播控制','01 / 0C','Type7F + Length04 + 4B结果','不与配网0D共用地址'],['配网信息','01 / 0D','单向下发，无应用响应','Wi-Fi / HaLow采用各自字段组'],['配网状态','01 / 0E','查询返回 / 主动上报','同形数据不作精确事务归因']].map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="public-flow-grid" data-note="11"><div class="workbench-controls"><h3>配网交互演示</h3><label class="field"><span>网络类型</span>${select('network',[[0,'Wi-Fi'],[1,'HaLow']],s.remoteType)}</label><div class="btn-row">${button('下发配网信息','send')}${button('查询配网状态','query')}</div><p class="help">下发0D不等待应用响应。0E也可独立查询当前状态，重连后不必先重发配网参数。</p><label class="field"><span>设备状态模拟</span>${select('status',labels.map((l,i)=>[i,l]),s.simulatedStatus)}</label><div class="btn-row">${button('模拟设备主动上报','report')}${button('接收查询结果','query-result',!s.queryPending)}</div><div class="btn-row">${button('模拟DHCP失败','dhcp')}${button('模拟流程超时','timeout')}${button('清空配网演示','reset')}</div></div><div class="workbench-state"><h3>当前状态：${esc(labels[s.status])}</h3><span class="tag ${s.submitted?'blue':'gray'}">${s.submitted?'0D已发送 · 不等待应用响应':'尚未发送0D'}</span><p class="help">${s.queryPending?'已发0E查询，等待状态数据；查询响应与主动上报同形，不作精确归因。':'状态只由0E更新；发送0D不代表网络已连接成功。'}</p><div class="workbench-wire"><strong>应用层报文</strong><pre>${s.frame?esc(s.frame.hex):'操作后显示 SID + CID + TLV，不包含底层帧。'}</pre></div><div class="transport-timeline">${s.logs.slice(-8).reverse().map(x=>`<div>${esc(x.label)}<div class="mono muted">${esc(x.hex)}</div></div>`).join('')||'<div class="muted">尚无通信记录</div>'}</div></div></div>${alert(s)}<div class="notes-box spaced" data-note="12">配网0D为预定义单向下发；通用SID08/CID01～03使用串行请求响应。此处不新增任务ID、ref_id、0D回执或云绑定完成推断。</div></section>`;}
function renderVerify(c){const s=get(c),r=s.long;return `<section class="panel-body app-workbench" data-note="10"><h3>通用协议验算 <span class="tag outline">不修改产品采用记录</span></h3><p class="help">当前产品固定采用 ${esc(c.templateVersion)}。验算使用独立合成字段，不放宽当前产品的业务范围，也不修改产品元数据、字典或历史快照。</p><div class="public-flow-grid"><div class="workbench-controls" data-note="11"><h3>Length与长字段</h3><label class="field"><span>验算模板</span>${select('template',[['flat-v1-draft','旧模板 flat-v1-draft'],['flat-v2-draft','新模板 flat-v2-draft']],s.template)}</label><label class="field"><span>Value字节数（ASCII）</span>${select('size',[[0,'0B'],[127,'127B'],[128,'128B'],[255,'255B'],[2039,'2039B · 本写请求完整包2048B'],[2040,'2040B · 完整包超限'],[16383,'16383B · Length语法上界']],s.size)}</label><label class="field"><span>消费者模板能力</span>${select('consumer',[['both','支持新旧模板'],['v1','仅支持旧模板']],s.consumer)}</label><div class="btn-row">${button('生成并回读长字段','long')}${button('验证0D没有响应','reject-response')}</div><p class="help">Length bit7是续字节，Type bit7是容器，均不是链路分片标志；完整PDU仍≤2048B。</p></div><div class="workbench-state"><h3>验算结果</h3>${r?`<div class="status-strip"><span>Length：<strong class="mono">${esc(r.lengthHex)}</strong></span><span>${r.width}个长度字节</span><span>Value ${s.size}B</span></div><div class="banner ${r.error?'amber':'green'}"><div><strong>${esc(r.error||'编码与解码一致')}</strong><p>${esc(r.message||('完整应用PDU '+r.bytes+'B'))}</p></div></div><pre class="workbench-code">${esc(r.preview||'未生成完整PDU')}</pre>`:'<div class="empty-proof">选择长度后验算；长报文仅显示首64B和末16B。</div>'}${alert(s)}</div></div><div data-note="12" class="spaced"><h3>命令能力协商</h3><p class="help">APP支持SID08/CID01～05，设备只支持01、02、04。双方交集不包含动作CID03。</p><div class="btn-row">${button('计算双方能力交集','intersect')}${button('尝试调用未支持的动作','reject-command')}</div>${s.caps?`<table class="readonly-table"><thead><tr><th>服务</th><th>实际可用命令</th></tr></thead><tbody>${s.caps.services.map(x=>`<tr><td class="mono">0x${x.serviceId.toString(16).padStart(2,'0')}</td><td class="mono">${x.commandIds.map(n=>'0x'+n.toString(16).padStart(2,'0')).join('、')}</td></tr>`).join('')}</tbody></table>`:''}</div><div data-note="13" class="notes-box spaced">新产品G1由系统关联新模板；旧P1/C1仍采用原模板。各产品形成独立协议，普通用户维护业务定义及三张编码绑定表；特殊结构由研发登记。</div></section>`;}
const local={services:[{serviceId:1,commandIds:[3,4,11,12,13,14]},{serviceId:8,commandIds:[1,2,3,4,5]}]},remote={services:[{serviceId:1,commandIds:[3,4,11,13,14]},{serviceId:8,commandIds:[1,2,4]}]};
function record(s,label,frame){s.frame=frame;s.logs.push({label,hex:frame.hex});}
function apply(c,action){const s=get(c),p=window.BLEPublicCommands;s.error=null;try{
 if(!p)throw new Error('公共指令模块未加载。');
 if(action==='reset'){all.delete(c.productId);return;}
 if(action==='send'){const a={remoteType:s.remoteType,ssid:'DEMO_NETWORK',password:'EXAMPLE_ONLY',token:'demo-token'},d=s.remoteType===0?{...a,encryptionType:3,cipher:2,mqttUrl:'mqtts://example.invalid'}:{...a,channelList:'1,2',bandwidth:1,txPower:20,superpower:0,cameraIp:2};record(s,'APP → 设备：0D信息；不等待应用响应',p.encode('provision.send','request',d));s.submitted=true;s.queryPending=false;s.status=4;}
 else if(action==='query'){record(s,'APP → 设备：0E查询',p.encode('provision.status','query',{remoteType:s.remoteType}));s.queryPending=true;}
 else if(['report','query-result','dhcp','timeout'].includes(action)){if(action==='query-result'&&!s.queryPending)throw new Error('先发送0E查询。');if(action==='dhcp'||action==='timeout')s.simulatedStatus=3;const e=action==='dhcp'?9:action==='timeout'?10:s.simulatedStatus===3?7:0;const f=p.encode('provision.status','report',{remoteType:s.remoteType,connectionStatus:s.simulatedStatus,errorCode:e,devBindStatus:0});s.status=p.decode('provision.status','report',f.bytes).data.connectionStatus;record(s,(action==='query-result'?'设备 → APP：0E查询结果':'设备 → APP：0E主动上报')+(e===9?'，09获取IP失败':e===10?'，0A整体流程超时':''),f);if(action==='query-result')s.queryPending=false;}
 else if(action==='reject-response')p.encode('provision.send','response',{resultCode:100000});
 else if(action==='intersect'||action==='reject-command'){s.caps=p.intersectCapabilities(local,remote);if(action==='reject-command'&&!s.caps.services.some(x=>x.serviceId===8&&x.commandIds.includes(3)))throw Object.assign(new Error('设备未声明SID08/CID03，已阻止动作下发。'),{code:'COMMAND_NOT_NEGOTIATED'});record(s,'设备命令能力列表',p.encode('capability.negotiate','response',remote));}
 else if(action==='long'){const l=p.encodeLength(s.size),d=p.decodeLength(l);s.long={lengthHex:l.map(x=>x.toString(16).padStart(2,'0').toUpperCase()).join(' '),width:d.width};try{if(s.consumer==='v1'&&s.template==='flat-v2-draft')throw Object.assign(new Error('消费者只支持旧模板；已拒绝新字典，不尝试猜编码。'),{code:'TEMPLATE_VERSION_UNSUPPORTED'});const f={address:1,type:'utf8',maxBytes:Math.max(1,s.size),value:'A'.repeat(s.size)},spec={templateVersion:s.template,sid:8,operation:'write',role:'request',messageId:1,fields:[f]},h=window.BLEProto.encodePDU(spec),v=window.BLEProto.decodePDU(spec,h);if(v.values['1']!==f.value)throw new Error('回读值不同。');const a=h.split(' ');Object.assign(s.long,{bytes:a.length,preview:a.length<=80?h:a.slice(0,64).join(' ')+'\n… '+(a.length-80)+' 字节 …\n'+a.slice(-16).join(' ')});}catch(e){Object.assign(s.long,{error:e.code||'ENCODING_ERROR',message:e.message});}}
 }catch(e){s.error=(e.code?e.code+'：':'')+e.message;}}
function field(c,id,v){const s=get(c);s.error=null;if(id==='network'){s.remoteType=Number(v);s.submitted=false;s.queryPending=false;s.status=4;s.frame=null;s.logs=[];}if(id==='status')s.simulatedStatus=Number(v);if(id==='size')s.size=Number(v);if(id==='template')s.template=v;if(id==='consumer')s.consumer=v;if(['size','template','consumer'].includes(id))s.long=null;}
document.addEventListener('click',e=>{const x=e.target.closest('[data-bench-action]');if(x&&host){apply(host.context(),x.dataset.benchAction);host.render();}});
document.addEventListener('change',e=>{const x=e.target.closest('[data-bench-field]');if(x&&host){field(host.context(),x.dataset.benchField,x.value);host.render();}});
window.BLEApplicationWorkbench={bind:api=>{host=api;},render:(c,mode)=>mode==='public'?renderPublic(c):renderVerify(c),snapshot:c=>JSON.parse(JSON.stringify(get(c))),apply,field};
})();
